window.ScripturaLexicons.BDAG_PART_0220 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-01\" data-source=\"BDAG\" data-search=\"λίψ, λιβός, ὁ substantivo masculino sudoeste; sul BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λίψ, λιβός, ὁ</td><td>substantivo masculino</td><td>sudoeste; sul</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-02\" data-source=\"BDAG\" data-search=\"Λογγῖνος, ου, ὁ nome próprio masculino Longino; cognome romano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λογγῖνος, ου, ὁ</td><td>nome próprio masculino</td><td>Longino; cognome romano</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-03\" data-source=\"BDAG\" data-search=\"Λόγγος, ου, ὁ nome próprio masculino Longo; nome próprio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λόγγος, ου, ὁ</td><td>nome próprio masculino</td><td>Longo; nome próprio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-04\" data-source=\"BDAG\" data-search=\"λογεία, ας, ἡ substantivo feminino coleta de dinheiro; contribuição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λογεία, ας, ἡ</td><td>substantivo feminino</td><td>coleta de dinheiro; contribuição</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-05\" data-source=\"BDAG\" data-search=\"λογίζομαι verbo calcular; atribuir; considerar; pensar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λογίζομαι</td><td>verbo</td><td>calcular; atribuir; considerar; pensar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-06\" data-source=\"BDAG\" data-search=\"λογικός, ή, όν adjetivo racional; espiritual; refletido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λογικός, ή, όν</td><td>adjetivo</td><td>racional; espiritual; refletido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-07\" data-source=\"BDAG\" data-search=\"λόγιον, ου, τό substantivo neutro oráculo; dito divino; declaração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λόγιον, ου, τό</td><td>substantivo neutro</td><td>oráculo; dito divino; declaração</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-08\" data-source=\"BDAG\" data-search=\"λόγιος, ία, ιον adjetivo eloquente; culto; erudito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λόγιος, ία, ιον</td><td>adjetivo</td><td>eloquente; culto; erudito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-09\" data-source=\"BDAG\" data-search=\"λογισμός, οῦ, ὁ substantivo masculino raciocínio; cálculo; pensamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λογισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>raciocínio; cálculo; pensamento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-10\" data-source=\"BDAG\" data-search=\"λογομαχέω verbo disputar sobre palavras BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λογομαχέω</td><td>verbo</td><td>disputar sobre palavras</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-11\" data-source=\"BDAG\" data-search=\"λογομαχία, ας, ἡ substantivo feminino contenda de palavras; logomaquia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λογομαχία, ας, ἡ</td><td>substantivo feminino</td><td>contenda de palavras; logomaquia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-12\" data-source=\"BDAG\" data-search=\"λόγος, ου, ὁ substantivo masculino palavra; mensagem; prestação de contas; Logos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λόγος, ου, ὁ</td><td>substantivo masculino</td><td>palavra; mensagem; prestação de contas; Logos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-13\" data-source=\"BDAG\" data-search=\"λόγχη, ης, ἡ substantivo feminino lança; ponta de lança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λόγχη, ης, ἡ</td><td>substantivo feminino</td><td>lança; ponta de lança</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-14\" data-source=\"BDAG\" data-search=\"λοιδορέω verbo insultar; injuriar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λοιδορέω</td><td>verbo</td><td>insultar; injuriar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-15\" data-source=\"BDAG\" data-search=\"λοιδορία, ας, ἡ substantivo feminino injúria; insulto; censura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λοιδορία, ας, ἡ</td><td>substantivo feminino</td><td>injúria; insulto; censura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-16\" data-source=\"BDAG\" data-search=\"λοίδορος, ου, ὁ substantivo masculino injuriador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λοίδορος, ου, ὁ</td><td>substantivo masculino</td><td>injuriador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-17\" data-source=\"BDAG\" data-search=\"λοιμικός, ή, όν adjetivo pestilento; pestífero BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λοιμικός, ή, όν</td><td>adjetivo</td><td>pestilento; pestífero</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-18\" data-source=\"BDAG\" data-search=\"λοιμός, οῦ, ὁ substantivo masculino peste; epidemia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λοιμός, οῦ, ὁ</td><td>substantivo masculino</td><td>peste; epidemia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-19\" data-source=\"BDAG\" data-search=\"λοιμός, ή, όν adjetivo; substantivo pestilento; inimigo público BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λοιμός, ή, όν</td><td>adjetivo; substantivo</td><td>pestilento; inimigo público</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0220-20\" data-source=\"BDAG\" data-search=\"λοιπός, ή, όν adjetivo; advérbio restante; demais; por fim BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λοιπός, ή, όν</td><td>adjetivo; advérbio</td><td>restante; demais; por fim</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0220-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίψ, λιβός, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λίψ</span>, <span class=\"greek\">λιβός</span>, <span class=\"greek\">ὁ</span> acusativo <span class=\"greek\">λίβα</span> (<span class=\"greek\">λείβω</span> «verter, gotejar»; Hdt. e outros; ins, pap, LXX; Jos., Bell. 1, 409, Ant. 3, 294; cf. Dssm., B 139 [BS 141f]) o sudoeste; quanto a um porto: <span class=\"greek\">βλέπειν</span> <span class=\"greek\">κατά</span> estar aberto para sudoeste <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:12</a> (veja EGoodspeed, Exp. 6th ser., 8, 1903, 130f, APF, 3, 1906, 406f; Haenchen ad loc.). No Antigo Testamento, quase sempre significa «sul» (veja Dssm., no lugar citado) 1 Cl 10:4 (Gen 13:14).—DELG s.v. <span class=\"greek\">λείβω</span> C. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λογγῖνος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λογγῖνος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (cognome latino; veja Groag-Stein, Prosopographia J 384 [século I d.C.]; IGLSyria 359, 3; pap; veja também o índice de Aa 1, 301 e Acta Pilati Ea p. 283, 3 Tdf.) Longino, um prefeito, assim lido por CSchmidt AcPl Ha 9, 17f: <span class=\"greek\">τῷ</span>] <span class=\"greek\">προφέκτῳ</span> <span class=\"greek\">Λογ</span>[<span class=\"greek\">γίνῳ</span> … ] com base no copta (quanto a isso <span class=\"greek\">τῷ</span> <span class=\"greek\">πραιφέκτῳ</span> <span class=\"greek\">Λόγγῳ</span> Aa I 112, 4. Reconstituição semelhante feita por Schmidt 9, 30; 10, 7; 17 etc.). Veja o verbete seguinte.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λόγγος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λόγγος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (cognome latino; pap; Jos., Bell. 6, 186) Longo Aa I 112, 4 (paralelo em AcPl Ha 9, 17f). Veja o verbete anterior.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λογεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">λογεύω</span> «arrecadar» contribuições, impostos etc., veja Dssm. BS 142–44; ins, pap: muitos exemplos nas obras citadas abaixo) coleta de dinheiro (<span class=\"greek\">λογεία</span> é etimologicamente correta; <span class=\"greek\">λογία</span> predomina nos manuscritos e nas edições; veja B-D-F. §23; Mlt-H. 339), especialmente uma coleta destinada a fins religiosos (PSI 262, 3 [século I d.C.] <span class=\"greek\">λ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; O. Wilck no. 412, 5; 414, 5; veja ibid. I 253–56 sobre o termo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:1</a>. <span class=\"greek\">λογεῖαι</span> <span class=\"greek\">γίνονται</span> fazem-se coletas v. 2.—Dssm., B 139ff, NB 46f (BS 142–44; 219f)], LO 83f (LAE 104); Mayser 417; WOtto, Priester u. Tempel I 1905, 359ff; KHoll, SBBerlAk 1921, 939f; WFranklin, D. Koll. des Pls, diss. Hdlbg. ’38; DGeorgi, D. Kollekte d. Paulus für Jerusalem ’65.—DELG s.v. <span class=\"greek\">λέγω</span> B 2. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογίζομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λογίζομαι</span> (<span class=\"greek\">λόγος</span>) imperfeito <span class=\"greek\">ἐλογιζόμην</span>; futuro <span class=\"greek\">λογιοῦμαι</span> LXX; 1º aoristo <span class=\"greek\">ἐλογισάμην</span>; perfeito <span class=\"greek\">λελόγιμαι</span> LXX. Na voz passiva: 1º aoristo <span class=\"greek\">ἐλογίσθην</span>; 1º futuro <span class=\"greek\">λογισθήσομαι</span>. Médio depoente (B-D-F §311; Rob. 816; 819) (Soph., Hdt.+) originalmente termo matemático e contábil, depois usado para processos cognitivos. Na literatura aqui considerada, especialmente empregado por Paulo; veja GThomas, ET 17, 1906, 211ff.</p><p class=\"entry-text\">① determinar por processo matemático, contar, calcular, frequentemente em sentido figurado</p><p class=\"entry-text\">ⓐ contar, levar em conta <span class=\"greek\">τὶ</span>, algo <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀγάπη</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">λογίζεται</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κακόν</span> o amor não contabiliza as ofensas (REB) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:5</a> (cf. Zech 8:17). <span class=\"greek\">λ</span>. <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> imputar algo a alguém, para puni-lo por isso (Simplicius em Epict. p. 79, 15 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἁμαρτίαν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πράττοντι</span> <span class=\"greek\">λογίζονται</span>; TestZeb 9:7; Just., D. 141, 2f) <span class=\"greek\">μὴ</span> <span class=\"greek\">λογιζόμενος</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">παραπτώματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:19</a>.—<span class=\"greek\">οὗ</span> (variante textual <span class=\"greek\">ᾧ</span>) <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">λογίσηται</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">ἁμαρτίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:8</a>; 1 Cl 50:6 (ambos em Ps 31:2; cf. 1 Cl 60:2). Na voz passiva (Lev 17:4) <span class=\"greek\">μὴ</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">λογισθείη</span> (quanto à forma, veja Mlt-H. 217) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:16</a>.—Mas «lançar na conta de alguém» também pode significar creditar <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐργαζομένῳ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μισθὸς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">λογίζεται</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">χάριν</span> o salário do trabalhador não é contabilizado como favor (mas como direito) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:4</a>. <span class=\"greek\">ᾧ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">λογίζεται</span> <span class=\"greek\">δικαιοσύνην</span> vs. 6. Na voz passiva, <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">λογισθῆναι</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δικαιοσύνην</span> vs. 11.—<span class=\"greek\">λ</span>. <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> creditar algo a alguém como alguma coisa; na voz passiva <span class=\"greek\">ἐλογίσθη</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">δικαιοσύνην</span> (segundo Gen 15:6; cf. Ps 105:31; 1 Macc 2:52) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:3</a>, 5, 9, 22 (WDiezinger, NovT 5, ’62, 288–98 [uso rabínico de <span class=\"greek\">λογ</span>.]); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:23</a>; 1 Cl 10:6.—Cf. também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:10</a>, 23f.—H-WHeidland, D. Anrechnung des Glaubens zur Gerechtigkeit ’36; FDanker, em Gingrich Festschr. ’72, 104.—<span class=\"greek\">λ</span>. <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span> lançar na conta de alguém, imputar a alguém (cf. a terminologia comercial OGI 595, 15 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἕτερα</span> <span class=\"greek\">ἀναλώματα</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">ἐλογισάμεθα</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span> <span class=\"greek\">βαρῶμεν</span>; PFay 21, 9) <span class=\"greek\">μή</span> <span class=\"greek\">τις</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐμὲ</span> <span class=\"greek\">λογίσηται</span> para que ninguém o atribua a mim <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:6</a>.</p><p class=\"entry-text\">ⓑ como resultado de um cálculo, avaliar, estimar, considerar, reputar (Hyperid. 2, 20; TestSol 4:11) <span class=\"greek\">εἰς</span> <span class=\"greek\">οὐθὲν</span> <span class=\"greek\">λογισθῆναι</span> ser considerado como nada (Is 40:17; Wsd 3:17; 9:6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:27</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">τέκνα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐπαγγελίας</span> <span class=\"greek\">λογίζεται</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">σπέρμα</span> os filhos da promessa são considerados descendência <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:8</a> (cf. La 4:2). <span class=\"greek\">οὐχ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀκροβυστία</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">περιτομὴν</span> <span class=\"greek\">λογισθήσεται</span>; não será a sua incircuncisão considerada circuncisão? 2:26. <span class=\"greek\">οὔτε</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">νομιζομένους</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἑλλήνων</span> <span class=\"greek\">θεοὺς</span> <span class=\"greek\">λογίζονται</span> eles não reconhecem as divindades honradas pelos gregos Dg 1:1.—Contar, classificar (PLond II, 328, 8 p. 75 [século II d.C.] quanto a um filhote de camelo: <span class=\"greek\">λογιζομένου</span> <span class=\"greek\">νυνὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τελείοις</span>=«que agora é classificado entre os adultos») <span class=\"greek\">μετὰ</span> <span class=\"greek\">ἀνόμων</span> <span class=\"greek\">ἐλογίσθη</span> foi contado entre os criminosos (Is 53:12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:27</a> [28] variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:37</a>. Também (exatamente como na LXX) <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀνόμοις</span> <span class=\"greek\">ἐλογίσθη</span> 1 Cl 16:13. <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐθνῶν</span> <span class=\"greek\">ἐλογίσθησαν</span> foram contados entre as nações Hs 8, 9, 3.—<span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐλογίσθη</span> foi tido em desconsideração 1 Cl 16:3 (Is 53:3).—<span class=\"greek\">λ</span>. <span class=\"greek\">τινα</span> <span class=\"greek\">ὡς</span> com acusativo considerar, reputar alguém como: <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">λογιζέσθω</span> <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ὑπηρέτας</span> <span class=\"greek\">Χριστοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:1</a>. <span class=\"greek\">λ</span>. <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">περιπατοῦντας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:2b</a>. Pass. <span class=\"greek\">ἐλογίσθημεν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">πρόβατα</span> <span class=\"greek\">σφαγῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:36</a> (Ps 43:23). <span class=\"greek\">πιστοὶ</span> <span class=\"greek\">λογισθέντες</span> considerados crentes Dg 11:2. <span class=\"greek\">ὁ</span> <span class=\"greek\">σήμερον</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">λογισθείς</span> aquele que hoje é celebrado como Filho 11:5 (Ps 2:7). <span class=\"greek\">λ</span>. <span class=\"greek\">τινα</span> seguido de acusativo e infinitivo (Is 53:4) <span class=\"greek\">λογίζεσθε</span> <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">νεκρούς</span> considerai-vos mortos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:11</a>. <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">ἐλογισάμεθα</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πόνῳ</span> julgávamos que ele estava sofrendo (como castigo) 1 Cl 16:4.</p><p class=\"entry-text\">② pensar cuidadosamente sobre uma questão, pensar (a respeito), considerar, ponderar, ocupar a mente com <span class=\"greek\">τὶ</span>, alguma coisa (PsSol 2, 28b; ApcEsdr 3:9; Philo, Leg. All. 3, 227 <span class=\"greek\">ταῦτα</span>; Jos., Ant. 6, 211) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:8</a>. Seguido de <span class=\"greek\">ὅτι</span> (PsSol 2, 28a; Philo, Somn. 2, 169; Jos., Ant. 11, 142; Ath., R. 9 p. 57, 30) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.50\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:19</a>. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ὅτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:11</a>, 7 (aqui acrescenta-se <span class=\"greek\">ἐφ</span>’ [variante textual <span class=\"greek\">ἀφ</span>’] <span class=\"greek\">ἑαυτοῦ</span>, «em sua própria mente»); B 1:5. Com <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτῷ</span> e discurso direto Hs 5, 2, 4 (cf. GrBar 4:12); com <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυταῖς</span> e pergunta direta em seguida <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:1</a> D; também <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">καρδίαις</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">πότερον</span> … <span class=\"greek\">ἤ</span> Hs 9, 28, 4.—Ter em mente, propor, intentar Dg 7:3 (Mel., P. 63, 455); com infinitivo seguinte (X., An. 2, 2, 13; 1 Macc 6:19) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:2a</a>. Conceber <span class=\"greek\">τὶ</span>, alguma coisa (Ps 51:4) <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἑαυτῶν</span> como (se fosse) de nós mesmos 3:5. Raciocinar ou fazer planos (Wsd 2:1) <span class=\"greek\">ὡς</span> <span class=\"greek\">νήπιος</span> como criança <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:11</a>.</p><p class=\"entry-text\">③ ter uma opinião sobre algo, pensar, crer, ser de parecer com <span class=\"greek\">ὅτι</span> em seguida (Just., A I, 8, 1 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:18</a>. Com acusativo e <span class=\"greek\">ὅτι</span> em seguida: <span class=\"greek\">λογίζῃ</span> <span class=\"greek\">τοῦτο</span> … , <span class=\"greek\">ὅτι</span>; imaginas que? 2:3. Seguido de acusativo e infinitivo (Wsd 15:12; Just., A I, 53, 1; Tat., Ath.) <span class=\"greek\">λογιζόμεθα</span> <span class=\"greek\">δικαιοῦσθαι</span> <span class=\"greek\">ἄνθρωπον</span> sustentamos que uma pessoa é justificada 3:28. <span class=\"greek\">λ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">κοινὸν</span> <span class=\"greek\">εἶναι</span> 14:14. <span class=\"greek\">ἐμαυτὸν</span> <span class=\"greek\">οὐ</span> (variante textual <span class=\"greek\">οὔπω</span>) <span class=\"greek\">λ</span>. <span class=\"greek\">κατειληφέναι</span> considero que ainda não alcancei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:13</a>. <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">λογίζομαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀθέους</span> <span class=\"greek\">ἐντρέπεσθαι</span> a quem, penso eu, até os ímpios respeitam ITr 3:2. Seguido apenas de infinitivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:5</a>; Dg 3:3 (Just., D. 102, 7 e outros).—<span class=\"greek\">ὡς</span> <span class=\"greek\">λογίζομαι</span> segundo penso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:31</a> variante textual.—DELG s.v. <span class=\"greek\">λέγω</span> 2. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λογικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> ([advérbio <span class=\"greek\">λογικῶς</span> Ath. 27, 2] expressão predileta dos filósofos desde Aristóteles; SIG 803, 5. Não ocorre na LXX, mas é frequente em Fílon, Justino, Taciano e Atenágoras) relativo ao que é cuidadosamente ponderado, racional, refletido <span class=\"greek\">λογικὴ</span> <span class=\"greek\">λατρεία</span> um culto racional (em sentido espiritual de dedicação) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:1</a> (o aspecto cognitivo antecipa a expressão <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δοκιμάζειν</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">τί</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θέλημα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; cf. Herm. Wr. 1, 31 <span class=\"greek\">λογικὴ</span> <span class=\"greek\">θυσία</span>; 13, 18; 21; Epict. 1, 16, 20f o canto de hinos constitui o serviço sagrado de um ser humano, como um <span class=\"greek\">λογικός</span>=alguém dotado de razão; 3, 1, 26 <span class=\"greek\">τὸ</span> <span class=\"greek\">λογικὸν</span> <span class=\"greek\">ἔχεις</span> <span class=\"greek\">ἐξαίρετον</span>· <span class=\"greek\">τοῦτο</span> <span class=\"greek\">κόσμει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">καλλώπιζε</span>. Philo, Spec. Leg. 1, 277 Deus não valoriza os animais sacrificiais, mas <span class=\"greek\">τοῦ</span> <span class=\"greek\">θύοντος</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">λογικόν</span>. TestLevi 3:6 <span class=\"greek\">λ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀναίμακτος</span> <span class=\"greek\">προσφορά</span> [variante textual <span class=\"greek\">θυσία</span>]; Ath., 13, 2; Eus., HE 4, 23, 13; cf. o padrão exortativo de Plut., Mor. 478de.—Rtzst., Mysterienrel.3 328f; Ltzm., Hdb. comentário específico sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:1</a>; BSchmidt, D. geistige Gebet, diss. Bresl. 1916; OCasel, Jahrb. f. Liturgiewissensch. 4, 1924, 38ff; CMoule, JTS nova série 1, ’50, 34f). Muito provavelmente <span class=\"greek\">τὸ</span> <span class=\"greek\">λογικὸν</span> <span class=\"greek\">ἄδολον</span> <span class=\"greek\">γάλα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:2</a> deve ser entendido de modo correlato leite espiritual puro; deve-se ter em mente que <span class=\"greek\">λ</span>. significa «espiritual» não só no sentido de <span class=\"greek\">πνευματικός</span>, mas também em contraste com «literal», no sentido de «metafórico» (cf. Pel-Leg. p. 20: o bispo é o pastor <span class=\"greek\">τῶν</span> <span class=\"greek\">λογικῶν</span> <span class=\"greek\">προβάτων</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>; Eus., HE 1, 1, 4 <span class=\"greek\">ἐκ</span> <span class=\"greek\">λογικῶν</span> <span class=\"greek\">λειμώνων</span>; veja DMcCartney, ZNW 82, ’91, 128–32, com ênfase na conexão helênica entre razão e comunicação verbal).—DELG s.v. <span class=\"greek\">λέγω</span> B 2. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λόγιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λόγιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Eur., Hdt.+, principalmente quanto a ditos divinos breves: Hdt. 8, 60, 3; Thu. 2, 8, 2; Polyb. 3, 112, 8; 8, 30, 6; Diod S 2, 14, 3; 2, 26, 9; 4, 65, 3 al.; Aelian, VH 2, 41. Igualmente na LXX [TManson, Goguel Festschr. ’50, 142f]; TestLevi 8:2; TestBenj 9:1 variante textual; EpArist 177; Philo, Congr. Erud. Grat. 134, Fuga 60, Mos. 2, 262, Praem. 1, Vi. Cont. 25; Jos., Bell. 6, 311; Just.) dito, declaração; na literatura aqui considerada, somente no plural (como também predomina em outros escritores); quanto às revelações recebidas por Moisés <span class=\"greek\">λόγια</span> <span class=\"greek\">ζῶντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:38</a>. Quanto às promessas de Deus aos judeus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:2</a> (JDoeve, Studia Paulina [JdeZwaan Festschr.] ’53, 111–23). Quanto a palavras das Escrituras em geral (como em Plut., Fab. 4, 5 quanto a palavras dos livros sibilinos; em contraste com o singular de uma afirmação bíblica: Just., A I, 32, 14 <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">λόγιον</span> [Is 11:1]; Did., Gen. 122, 24 [Eccl 8:1]); <span class=\"greek\">τὰ</span> <span class=\"greek\">λόγια</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (LXX; Iren. 1, 8, 1 [Harv. I 68, 11]; cf. <span class=\"greek\">τὰ</span> <span class=\"greek\">θεῖα</span> <span class=\"greek\">λ</span>. Did., Gen. 174, 16) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:12</a>.—1 Cl 13:4; 19:1; 53:1. <span class=\"greek\">τὰ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">παιδείας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> os oráculos do ensino de Deus 62:3 (cf. <span class=\"greek\">τὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">σοφίας</span> <span class=\"greek\">λ</span>. Orig., C. Cels. 5, 29, 50). Também quanto a ditos do Novo Testamento 2 Cl 13:3 (cf. v. 4). Igualmente <span class=\"greek\">τὰ</span> <span class=\"greek\">λόγια</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> os ditos do Senhor (Jesus; Marinus, Vi. Procli 26 p. 163, 50 Boiss. <span class=\"greek\">τὰ</span> <span class=\"greek\">Ὀρφέως</span> <span class=\"greek\">λόγια</span>; TestBenj 9:1 variante textual <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">λογίων</span> <span class=\"greek\">Ἑνώχ</span>) Pol 7:1; cf. Papias (2:15f; em Eus., HE 3, 39, 1); AcPlCor 2:3 (Clem. Al., Quis Div. Salv. 3, 1; Iren. 1, Praef. 1 [Harv. I 2, 4]; cf. Just., D. 18, 1). Quanto aos pronunciamentos de cristãos dotados do dom de ministrar pela palavra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:11</a>. Quanto a Pápias, veja também <span class=\"greek\">ἐξήγησις</span> e <span class=\"greek\">κυριακός</span>.—PNepper-Christensen, Mt ein Judenchristliches Evangelium? ’58, 37–56.—DELG s.v. <span class=\"greek\">λέγω</span> B 2. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λόγιος, ία, ιον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λόγιος</span>, <span class=\"greek\">ία</span>, <span class=\"greek\">ιον</span> (veja <span class=\"greek\">λόγος</span>; [superlativo <span class=\"greek\">λογιώτατος</span> Ath. 28, 4] Pind. e outros; ins, pap)</p><p class=\"entry-text\">① eloquente (Plut., Pomp. 51, 8; Lucian, Pseudolog. 24, Pro Merc. Cond. 2 Hermes como <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγιος</span>; Philo, Mut. Nom. 220, Cher. 116. Esse significado é rejeitado por Frínico [p. 198 Lob.]; defendido por Field [Notes 129]).</p><p class=\"entry-text\">② erudito, culto (Hdt. 1, 1; 2, 3; Aristot., Pol. 2, 8; Heliod. 4, 7, 4 a respeito de um <span class=\"greek\">ἰατρός</span>; EpArist 6; Philo, Mos. 1, 23 al.; Jos., Bell. 1, 13, Ant. 17, 149; Ar. 13, 7; Tat. 40, 1.—Como substantivo Orig., C. Cels. 1, 12, 34; 5, 21, 13). Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:24</a>, em que Apolo é chamado <span class=\"greek\">ἀνὴρ</span> <span class=\"greek\">λ</span>. (como em Ps.-Libanius, Charact. Ep. p. 20, 12; PLond 2710 recto, 6, citado em HTR 29, ’36, 40f; 45; Philo, Poster. Cai. 53), ambos os significados são prováveis, embora as versões antigas (Lat., Syr., Armen.) prefiram o primeiro.—EOrth, Logios 1926.—DELG s.v. <span class=\"greek\">λέγω</span> B 2. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λογισμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (Thu. +).</p><p class=\"entry-text\">① produto de processo cognitivo, cálculo, raciocínio, reflexão, pensamento; na literatura aqui considerada, no plural. Com <span class=\"greek\">ἔννοιαι</span> pensamentos e sentimentos Pol 4:3 (Ath. 9, 1). <span class=\"greek\">μεταξὺ</span> <span class=\"greek\">ἀλλήλων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λ</span>. <span class=\"greek\">κατηγορούντων</span> como seus pensamentos se acusam mutuamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:15</a> (aqui os pensamentos são personificados como acusação e defesa; Straub 30; cf. Pr 19:21). Não raro em sentido desfavorável (como, por exemplo, Vett. Val. 49, 8; 173, 11; <span class=\"greek\">λ</span>. <span class=\"greek\">κακοί</span> Pr 6:18; cf. Wsd 1:3, 5; 11:15) <span class=\"greek\">οἱ</span> <span class=\"greek\">προκατέχοντές</span> <span class=\"greek\">σου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">διάνοιαν</span> <span class=\"greek\">λογισμοί</span> os pensamentos (preconcebidos) que ocupam a tua mente Dg 2:1. <span class=\"greek\">λογισμοὶ</span> <span class=\"greek\">ἐθνῶν</span> os desígnios das nações 1 Cl 59:3. <span class=\"greek\">λογισμοὺς</span> <span class=\"greek\">καθαιροῦντες</span> destruímos sofismas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:4</a>.</p><p class=\"entry-text\">② capacidade de raciocinar, faculdade racional, sabedoria (Epicuro em Diog. L. 10, 132 <span class=\"greek\">νήφων</span> <span class=\"greek\">λογισμός</span>=raciocínio sóbrio; TestGad 6:2 <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μίσους</span> <span class=\"greek\">ἐτάρασσέ</span> <span class=\"greek\">μου</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λογισμὸν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀνελεῖν</span> <span class=\"greek\">αὐτόν</span>; TestJob 21:4 <span class=\"greek\">ἀνελάμβανον</span> <span class=\"greek\">λογισμὸν</span> <span class=\"greek\">μακρόθυμον</span>; Jos., Bell. 2, 31; Just., A I, 17, 3 al.) <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">αἴσθησιν</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">κ</span>. <span class=\"greek\">λογισμόν</span> uma pessoa tem a capacidade de sentir e pensar Dg 2:9 (<span class=\"greek\">λ</span>. com <span class=\"greek\">αἴσθησις</span> como em Philo, Praem. 28).—DELG s.v. <span class=\"greek\">λέγω</span> B 2. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογομαχέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λογομαχέω</span> (Eustath., Opusc. p. 47, 96) discutir sobre palavras, disputar por sutilezas verbais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:14</a>.—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογομαχία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λογομαχία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">λόγος</span> + <span class=\"greek\">μάχομαι</span>; Conon [século I a.C./século I d.C.: 26 Fgm. 1, 38 p. 204, 1 Jac. [Narrat. 38 em Fócio, Bibl. Cod. 186]; Porphyr., Ep. ad Anebonem 2, 19 p. 29, 19; Eus., PE 14, 10, 2; Cat. Cod. Astr. VIII/1 p. 167, 21) contenda verbal, disputa acerca de palavras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:9</a> variante textual—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λόγος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λόγος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (substantivo verbal de <span class=\"greek\">λέγω</span>, no sentido de «recolher»; Hom.+).</p><p class=\"entry-text\">① comunicação pela qual o pensamento se expressa, palavra</p><p class=\"entry-text\">ⓐ quanto ao enunciado, principalmente oral.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. como expressão, palavra (a capacidade oratória aliada a realizações excepcionais constituía traço distintivo na sociedade helênica; daí a frequente associação entre <span class=\"greek\">λ</span>. e <span class=\"greek\">ἔργον</span>, «ação»; formulação semelhante já em Il. 9, 443 <span class=\"greek\">μύθων</span> <span class=\"greek\">τε</span> <span class=\"greek\">ῥητῆρ</span>’ <span class=\"greek\">ἔμεναι</span> <span class=\"greek\">πρηκτῆρά</span> <span class=\"greek\">τε</span> <span class=\"greek\">ἔργων</span>; Polystrat. p. 33 <span class=\"greek\">μὴ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">μόνον</span> <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">ἔργω</span>; Just., A II, 4, 2 <span class=\"greek\">ἢ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἔργῳ</span> e D. 35, 7 <span class=\"greek\">λόγον</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">πρᾶξιν</span>) <span class=\"greek\">δυνατὸς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἔργῳ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">λόγῳ</span>, isto é, personagem extraordinária <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:19</a>; plural quanto a Moisés <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:22</a> (o contraste expresso com um verbo Choix 20, 6–8 <span class=\"greek\">ποιεῖ</span> <span class=\"greek\">ἀγαθὸν</span> <span class=\"greek\">ὄτι</span> <span class=\"greek\">δύναται</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔργῳ</span> quanto a Apolodoro, benfeitor em Cízico, cidade próspera da Frígia; semelhantemente, New Docs 7, 233, no. 10, 8f <span class=\"greek\">πολιτευόμενος</span> … <span class=\"greek\">λόγῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔργῳ</span>; cf. IKourion 32, 8; sem contraste Diod S 13, 101, 3 <span class=\"greek\">ἄνδρας</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">δυνατούς</span>; quanto a construções semelhantes com <span class=\"greek\">λέγω</span> e <span class=\"greek\">πράσσω</span>, veja Danker, Benefactor 339–43). Cp. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:21</a> variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:18</a> (cf. Theognis 1, 87f Diehl3 <span class=\"greek\">μή</span> <span class=\"greek\">μ</span>’ <span class=\"greek\">ἔπεσιν</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">στέργε</span> <span class=\"greek\">κτλ</span>.—Quanto ao contraste <span class=\"greek\">λόγῳ</span> … <span class=\"greek\">ἀληθείᾳ</span>, cf. Diod S 13, 4, 1). Em contraste com uma ação pecaminosa, ocorre também <span class=\"greek\">λόγος</span> <span class=\"greek\">ἁμαρτίας</span>, «palavra pecaminosa» Judaicon 172, 9. Com <span class=\"greek\">γνῶσις</span>: <span class=\"greek\">ἐν</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πάσῃ</span> <span class=\"greek\">γνώσει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:5</a>. <span class=\"greek\">ἰδιώτης</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span>, <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">οὐ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">γνώσει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:6</a>. (Em oposição a <span class=\"greek\">δύναμις</span>, «manifestação de poder») <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:19</a>, 20. <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐγενήθη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">μόνον</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">δυνάμει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:5</a> (cf. Ar. 13, 7 of mythical accounts <span class=\"greek\">οὐδέν</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">μόνον</span> <span class=\"greek\">λόγοι</span> ‘não passam de palavras’). Com <span class=\"greek\">ἐπιστολή</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:2</a>, 15. Com <span class=\"greek\">ἀναστροφή</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:1b</a>. Em oposição a «calar-se»: IRo 2:1.—<span class=\"greek\">μόνον</span> <span class=\"greek\">εἰπὲ</span> <span class=\"greek\">λόγῳ</span> dize somente uma palavra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:8</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:7</a> (Ath. 17, 1 <span class=\"greek\">ὡς</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">εἰπεῖν</span>; 29, 2; Phalaris, Ep. 121, 1 <span class=\"greek\">λόγῳ</span> <span class=\"greek\">λέγειν</span>; cf. schol. on Pla. 341a <span class=\"greek\">ἐν</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">μόνον</span> <span class=\"greek\">εἰπεῖν</span>). <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἐδύνατο</span> <span class=\"greek\">ἀποκριθῆναι</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">λόγον</span> ninguém conseguia responder-lhe sequer uma palavra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:46</a>; cf. 15:23 (cf. TestAbr A 16 p. 98, 11 [Stone p. 44] <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀπεκρίθη</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">λόγον</span>).—A palavra (poderosa) daquele que realiza milagres <span class=\"greek\">ἐξέβαλεν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πνεύματα</span> <span class=\"greek\">λόγῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:16</a> (uso raro de <span class=\"greek\">λ</span>. como «enunciado único», veja L-S-J-M s.v. VII).—<span class=\"greek\">διὰ</span> <span class=\"greek\">λόγου</span> oralmente (em oposição a «por carta») <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:27</a>.—Na passagem de texto incerto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:24</a> o texto tal como se apresenta em N., <span class=\"greek\">οὐδενὸς</span> <span class=\"greek\">λόγου</span> (variante textual <span class=\"greek\">λόγον</span>) <span class=\"greek\">ποιοῦμαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">τιμίαν</span>, pode bem significar: não considero minha vida digna de uma só palavra (cf. <span class=\"greek\">λόγου</span> <span class=\"greek\">ἄξιον</span> [<span class=\"greek\">ἄξιος</span> 1a] e nossa expressão «digno de menção»; veja Conzelmann ad loc.).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. A expressão pode assumir diversas formulações ou matizes temáticos: aquilo que se diz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:37</a>; afirmação (PGM 4, 334) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:20</a>; pergunta (Sext. Emp., Math. 8, 295; 9, 133; Diog. L. 2, 116) <span class=\"greek\">ἐρωτήσω</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">λόγον</span> farei a vós uma pergunta (cf. TestJob 36:5; GrBar 5:1; ApcSed 13:6; Jos., Ant. 12, 99) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:24</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:3</a>; oração (PGM 1, 25; 4, 90; 179; 230 al.; 5, 180; 196 al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:39</a>. <span class=\"greek\">ἡγούμενος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λ</span>. orador principal <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:12</a>. Com genitivo epexegético <span class=\"greek\">λ</span>. <span class=\"greek\">παρακλήσεως</span> 13:15. Com <span class=\"greek\">κήρυγμα</span>: nosso modo de apresentação e nossa proclamação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:4a</a> (mas veja os comentários). (Com <span class=\"greek\">διδασκαλία</span>) pregação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:17</a>; profecia (Biogr. p. 364 [Pythia]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:22</a>; 18:32. Ordem (Aeschyl., Pers. 363) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:5</a>, 7; por meio de carta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:14</a>. Notícia, relato (X., An. 1, 4, 7; Diod S 3, 40, 9; 19, 110, 1 <span class=\"greek\">λ</span>. <span class=\"greek\">διαδιδόναι</span>=difundir um relato; Appian, Iber. 80 §346, Maced. 4 §1 [ambos significam «rumor»]; Diod S 32, 15, 3 <span class=\"greek\">ἦλθεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>=a notícia chegou a alguém; Arrian, Anab. 7, 22, 1 <span class=\"greek\">λόγος</span> <span class=\"greek\">λέγεται</span> <span class=\"greek\">τοιόσδε</span>=conta-se uma história assim, Ind. 9, 2; Diod S 3, 18, 3 <span class=\"greek\">λ</span>.=história, narrativa; Jos., Ant. 19, 132; Tat. 27, 2 <span class=\"greek\">τοῦ</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">Ἡρακλέα</span> <span class=\"greek\">λόγου</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:15</a> (<span class=\"greek\">λ</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> como em X., An. 6, 6, 13; Jos., Ant. 19, 127) 7:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:23</a>. <span class=\"greek\">ἠκούσθη</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὦτα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐκκλησίας</span> a notícia chegou aos ouvidos da assembleia em Jerusalém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:22</a>. <span class=\"greek\">λόγον</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">σοφίας</span> ter aparência de sabedoria, passar por sabedoria <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:23</a> (cf. Pla., Epinomis 987b <span class=\"greek\">ἔχει</span> <span class=\"greek\">λόγον</span>; Demosth., C. Lept. 462 [20, 18] <span class=\"greek\">λόγον</span> <span class=\"greek\">τιν</span>’ <span class=\"greek\">ἔχον</span>; mas o significado 2f também é possível). Provérbio (Pla., Phdr. 17, 240c, Symp. 18, 195b, Gorg. 54, 499c, Leg. 6, 5, 757a; Socrat., Ep. 22, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.37\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:37</a> (Ps.-Callisth. 1, 13, 7 <span class=\"greek\">ἀληθῶς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>. seguido de um provérbio). Proclamação, instrução, ensino, mensagem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:32</a>; 10:39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:41</a>; 17:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:41</a>; 4:4; 10:44; 20:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:17</a>; 2:1. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:15</a> <span class=\"greek\">ζητήματα</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">λόγου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὀνομάτων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νόμου</span> o sentido parece ser aproximadamente este: questões controversas que envolvem disputas acerca de palavras e de vosso modo de viver com <span class=\"greek\">λ</span>. provavelmente referindo-se à apresentação de assuntos controversos que, por sua vez, suscitam debates acalorados (<span class=\"greek\">ζητήματα</span>). <span class=\"greek\">λόγος</span> <span class=\"greek\">σοφίας</span> proclamação de sabedoria, falar sabiamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:8a</a> (Ps.-Phoc. 129 <span class=\"greek\">τῆς</span> <span class=\"greek\">θεοπνεύστου</span> <span class=\"greek\">σοφίης</span> <span class=\"greek\">λ</span>.); correspondentemente <span class=\"greek\">λ</span>. <span class=\"greek\">γνώσεως</span> v. 8b. Cf. 14:9; 15:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:18</a>; 6:7; 10:10. <span class=\"greek\">λ</span>. <span class=\"greek\">μαρτυρίας</span> palavra de testemunho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:11</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">διδαχὴν</span> <span class=\"greek\">πιστὸς</span> <span class=\"greek\">λ</span>. a mensagem da fé, correspondente ao ensino <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:9</a>; o oposto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:17</a>. Discurso (Aristot. p. 14b, 2; Diod S 40, 5a) <span class=\"greek\">διὰ</span> <span class=\"greek\">λόγου</span> <span class=\"greek\">πολλοῦ</span> em um longo discurso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:32</a>; cf. 20:2. <span class=\"greek\">λ</span>. <span class=\"greek\">κολακείας</span> discurso lisonjeiro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:5</a>. Fala em geral <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:6</a>; D 2:5. <span class=\"greek\">ἐν</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">πταίειν</span> tropeçar naquilo que se diz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:2</a>.—Quanto à palavra, ordem ou incumbência de Deus (LXX; ParJer 5:19 <span class=\"greek\">κατηχῆσαι</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span>; SyrBar 13:2; ApcSed 14:10; Just., D. 84, 2; Ael. Aristid. ouve um <span class=\"greek\">ἱερὸς</span> <span class=\"greek\">λ</span>. à noite, proveniente de um deus: 28, 116 K.=49, p. 529 D.; Sextus 24) <span class=\"greek\">ἠκυρώσατε</span> <span class=\"greek\">τ</span>. <span class=\"greek\">λόγον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:6</a> (variante textual <span class=\"greek\">νόμον</span>, <span class=\"greek\">ἐντολήν</span>); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:13</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:38</a>; 8:55; 10:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:4</a> (Ps 50:6). Quanto à promessa de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:6</a>, 9 (mas esses dois versículos e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:14</a> abaixo provavelmente se ajustam melhor à acepção 2a), 28 (Is 10:22f). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:2</a>; 4:2 (veja <span class=\"greek\">ἀκοή</span> 4b); 7:28; 12:19. Quanto a B 15:1, veja 1a<span class=\"greek\">δ</span>. Toda a Lei (como indica a expressão <span class=\"greek\">εἴ</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἑτέρα</span> <span class=\"greek\">ἐντολή</span>, não limitada a uma lista reduzida de mandamentos), segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:9</a>. No que provavelmente constitui um jogo de palavras (veja 2a e b), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:14</a> (veja 2a abaixo) é resumido no <span class=\"greek\">λόγος</span> expresso em Lv 19:18.—Aquilo que Deus criou <span class=\"greek\">ἁγιάζεται</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">λόγου</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:5</a>; considerando o contexto, isso dificilmente se refere à palavra criadora de Deus (so SibOr 3, 20; PtK 2; <span class=\"greek\">πάντα</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">ποιήσας</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> Theoph. Ant. 2, 18 [144, 8]), mas a orações à mesa que utilizam expressões bíblicas. A palavra divina como juíza dos pensamentos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:12</a>. <span class=\"greek\">τελεσθήσονται</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:17</a>; cf. 19:9.—Quanto à revelação divina por meio de Cristo e seus mensageiros (Just., A I, 61, 9 <span class=\"greek\">λόγον</span> … <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀποστόλων</span> <span class=\"greek\">ἐμάθομεν</span> <span class=\"greek\">τοῦτον</span>) <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐφανέρωσεν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λ</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κηρύγματι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:3</a>. <span class=\"greek\">δέδωκα</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λ</span>. <span class=\"greek\">σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:14</a>; cf. vsveja 6, 17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:10</a>; 2:14. <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">βλασφημῆται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:5</a>. Afirma-se que os apóstolos e outros pregadores, em relação ao <span class=\"greek\">λόγος</span> de Deus: <span class=\"greek\">λαλεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:29</a>, 31; 13:46; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:7</a>; <span class=\"greek\">καταγγέλλειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:5</a>; 17:13; <span class=\"greek\">διδάσκειν</span> 18:11; <span class=\"greek\">μαρτυρεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:2</a>. A respeito de seus ouvintes se diz: <span class=\"greek\">τὸν</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἀκούειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:7</a>; <span class=\"greek\">δέχεσθαι</span> 8:14; 11:1. Acerca do próprio <span class=\"greek\">λ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> lemos: <span class=\"greek\">ηὔξανεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:7</a>; 12:24; 19:20; <span class=\"greek\">οὐ</span> <span class=\"greek\">δέδεται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:9</a>. Nessas passagens e em muitas outras, <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> é simplesmente a mensagem cristã, o evangelho: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:1</a>; 8:11, 21; 11:28 (Simplicius in Epict. p. 1, 20 <span class=\"greek\">μὴ</span> <span class=\"greek\">μόνον</span> <span class=\"greek\">ἀκουόντων</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">πασχόντων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λόγων</span>=deixar a mensagem exercer seu efeito em si próprio); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:2</a> (veja <span class=\"greek\">καταλείπω</span> 7c; quanto à provável metáfora comercial, veja 2a abaixo); 13:44 variante textual (em lugar de <span class=\"greek\">κυρίου</span>); 16:32 variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.36\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:17</a>; 4:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:9</a>; 6:9; 20:4; IPhld 11:1. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:13ab</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:5</a>.—Uma vez que essa «palavra divina» é levada à humanidade por meio de Cristo, sua palavra pode ser empregada no mesmo sentido: <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:24</a>; cf. 8:31, 37, 43, 51f; 12:48; 14:23f; 15:3, 20b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:8</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:16</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:1</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:25</a>; 12:24 variante textual; 13:44, 48f; 14:25 variante textual; 15:35, 36; 16:32 (cf. <span class=\"greek\">λ</span>. <span class=\"greek\">θεοῦ</span>); 19:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:1</a>. Pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:38</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:26</a>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:3</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:44</a>; veja também 1a<span class=\"greek\">δ</span>.—Ou é denominada simplesmente <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span>, a «Palavra», pois não haveria possibilidade de equívoco entre os cristãos: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:20</a>–23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:2</a>; 4:14–20, 33; 8:32 (veja 1a<span class=\"greek\">ε</span> abaixo); 16:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:2</a>; 8:12f, 15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:4</a>; 8:4; 10:36 (quanto à sintaxe, veja FNeirynck, ETL 60, ’84, 118–23); 11:19; 14:25 (cf. <span class=\"greek\">λ</span>. <span class=\"greek\">κυρίου</span> acima); 16:6; 17:11; 18:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:21ff</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:8</a>; 3:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:7</a>; AcPl Ha 7, 6 (assim também Mel., HE 4, 26, 13; Ath. 2, 3).—Por vezes a «Palavra» é definida mais precisamente por um genitivo: <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span> a palavra do reinado/governo (de Deus) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:19</a>. <span class=\"greek\">τῆς</span> <span class=\"greek\">σωτηρίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:26</a>. <span class=\"greek\">τῆς</span> <span class=\"greek\">καταλλαγῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:19</a>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:18</a>. <span class=\"greek\">δικαιοσύνης</span> (veja esse verbete 3a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:13</a>. <span class=\"greek\">ζωῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:16</a>. (<span class=\"greek\">τῆς</span>) <span class=\"greek\">ἀληθείας</span> (Theoph. Ant. 3, 4 [p. 212, 2]; cf. <span class=\"greek\">περὶ</span> <span class=\"greek\">ἀληθείας</span> Hippol., Ref. 10, 6, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:18</a>; AcPl Ha 8, 8 (Just., D. 121, 2). <span class=\"greek\">τῆς</span> <span class=\"greek\">χάριτος</span> <span class=\"greek\">αὐτοῦ</span> (=<span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:3</a>; 20:32. (De modo diferente, o plural <span class=\"greek\">οἱ</span> <span class=\"greek\">λόγοι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">χάριτος</span> palavras graciosas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:22</a>; cf. Marcellinus, Vi. Thu. 57 Hude <span class=\"greek\">λόγοι</span> <span class=\"greek\">εἰρωνείας</span>.) <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">εὐαγγελίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:7</a>; <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστιανισμοῦ</span> <span class=\"greek\">λ</span>. MPol 10:1. Em Ap 3:10, o evangelho é descrito por «Aquele que tem a chave de Davi» como <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑπομονῆς</span> <span class=\"greek\">μου</span> minha palavra de perseverança (W-S. §30, 12c). <span class=\"greek\">λ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ὑ</span>[<span class=\"greek\">πο</span>]<span class=\"greek\">μονῶν</span> AcPl Ha 6, 11. <span class=\"greek\">παρελάβετε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ὅτι</span> AcPl Ha 8, 25.—As cartas pastorais preferem a expressão <span class=\"greek\">πιστὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> (subentenda-se <span class=\"greek\">ἐστίν</span>; veja também <span class=\"greek\">πιστός</span> 1b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:15</a>; 3:1; 4:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:8</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:5</a>; 22:6. <span class=\"greek\">λ</span>. <span class=\"greek\">ὑγιής</span> pregação sadia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:8</a>; cf. o plural <span class=\"greek\">ὑγιαίνοντες</span> <span class=\"greek\">λόγοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:13</a> (sobre o uso medicinal das palavras para a mente ou alma, veja VLeinieks, The City of Dionysos ’96, 115–22, sobre Eur.).—O plural também é empregado em geral quanto aos ensinamentos cristãos, as palavras do evangelho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:4</a> (veja <span class=\"greek\">κατηχέω</span> 2a); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:18</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:6</a>. Quanto a <span class=\"greek\">λόγοι</span> <span class=\"greek\">κυριακοί</span> em lugar de <span class=\"greek\">λόγια</span> <span class=\"greek\">κυριακά</span> no título do escrito de Pápias, veja <span class=\"greek\">ἐξήγησις</span> 2.—JSchniewind, Die Begriffe Wort und Evangelium bei Pls, diss. Bonn 1910; RAsting (<span class=\"greek\">εὐαγγέλιον</span>, end).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. quanto a uma declaração ou observação individual: afirmação, declaração, fala <span class=\"greek\">ἀκούσαντες</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λ</span>. quando ouviram a declaração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:12</a>; cf. 19:11, 22; 22:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:36</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦτον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λ</span>. por causa desta tua declaração 7:29 (TestAbr A 15 p. 95, 29 [Stone p. 38] <span class=\"greek\">τὸν</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τοῦτον</span>; ApcMos 25 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">σου</span> <span class=\"greek\">κρινῶ</span> <span class=\"greek\">σε</span>). Cp. 10:22; 12:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:29</a>; 22:61 variante textual (em lugar de <span class=\"greek\">ῥήματος</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:39</a>, 50; 6:60; 7:36, 40 variante textual; 15:20a; 18:9; 19:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:5</a>; 7:29; 20:38; 22:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:15</a>. <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">εἴπῃ</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνθρώπου</span> quem profere uma palavra (difamatória) contra o Filho do Homem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:32</a> (<span class=\"greek\">λ</span>. <span class=\"greek\">εἰπεῖν</span> <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span> as Jos., Ant. 15, 81); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:10</a>. <span class=\"greek\">λόγος</span> <span class=\"greek\">σαπρός</span> fala nociva <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:29</a>. <span class=\"greek\">λόγον</span> <span class=\"greek\">ποιεῖσθαι</span> proferir um discurso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:2</a> D (cf. Hyperid. 3, 20; Jos., Ant. 11, 86).</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. o plural (<span class=\"greek\">οἱ</span>) <span class=\"greek\">λόγοι</span> é empregado, por um lado, para palavras proferidas em ocasiões diversas, discursos ou ensinamentos transmitidos por seres humanos ou transcendentes (TestAbr A 14 p. 94, 19 [Stone p. 36]; Jos., Ant. 4, 264; Just., D. 100, 3) <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λόγων</span> <span class=\"greek\">σου</span> <span class=\"greek\">δικαιωθήσῃ</span> (<span class=\"greek\">καταδικασθήσῃ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:37ab</a>; 24:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:40</a>; 7:22 (<span class=\"greek\">ἐν</span> <span class=\"greek\">λόγοις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔργοις</span> <span class=\"greek\">αὐτοῦ</span>. Quanto ao par palavra-ação, cf. Dio Chrys. 4, 6 as palavras (<span class=\"greek\">λόγοι</span>) e ações (<span class=\"greek\">ἔργα</span>) de Diógenes; veja <span class=\"greek\">α</span> acima). <span class=\"greek\">οἱ</span> <span class=\"greek\">δέκα</span> <span class=\"greek\">λόγοι</span> os dez mandamentos (Ex 34:28; Dt 10:4; Philo, Rer. Div. Her. 168, Decal. 32; Jos., Ant. 3, 138; cf. 91f; Did., Gen. 36, 10) B 15:1. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:24</a>; 20:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:4b</a>, 13; 14:19ab; <span class=\"greek\">κενοὶ</span> <span class=\"greek\">λ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:6</a>; AcPl Ox 6, 13 (cf. Aa 1, 241, 14); Dg 8:2; <span class=\"greek\">πλαστοὶ</span> <span class=\"greek\">λ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:3</a>. <span class=\"greek\">λ</span>. <span class=\"greek\">πονηροί</span> 3J 10.—Também quanto a palavras e expressões que constituem uma unidade, seja um discurso articulado (Jos., Ant. 15, 126; Just., A II, 12, 6, D. 11, 5; 81, 3 al.), uma conversa, partes de um mesmo ensinamento ou exposições sobre o mesmo assunto (Diod S 16, 2, 3 <span class=\"greek\">μετέσχε</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Πυθαγορίων</span> <span class=\"greek\">λόγων</span>; Dio Chrys. 37 [54], 1; Ael. Aristid. 50, 55 K.=26 p. 519 D.: <span class=\"greek\">οἱ</span> <span class=\"greek\">Πλάτωνος</span> <span class=\"greek\">λόγοι</span>; PsSol 17:43 [palavras do Messias]; AscIs 3:12 <span class=\"greek\">οἱ</span> <span class=\"greek\">λόγοι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Βελχειρά</span>) <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὅστις</span> <span class=\"greek\">ἀκούει</span> <span class=\"greek\">μου</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">λόγους</span> <span class=\"greek\">τούτους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:24</a>; cf. versículos 26, 28; 10:14; 19:1; 26:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:20</a>; 6:47; 9:28, 44. <span class=\"greek\">ἐπηρώτα</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">λόγοις</span> <span class=\"greek\">ἱκανοῖς</span> interrogou-o longamente 23:9. <span class=\"greek\">τίνες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">οὗτοι</span> <span class=\"greek\">οὓς</span> <span class=\"greek\">ἀντιβάλλετε</span>; que conversa é esta que estais mantendo? 24:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:40</a> (veja <span class=\"greek\">γ</span>); 10:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:24a</a>; 19:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:22</a>; 5:5, 24; 16:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:15</a>; 1 Cl 13:1; 46:7. <span class=\"greek\">λόγοις</span> <span class=\"greek\">φθοριμαίοις</span> AcPlCor 1:2.</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. assunto em discussão, questão, coisa em geral (Theognis 1055 Diehl; Hdt. 8, 65 <span class=\"greek\">μηδενὶ</span> <span class=\"greek\">ἄλλῳ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">τοῦτον</span> <span class=\"greek\">εἴπῃς</span>. Cf. hebraico <span class=\"hebrew\" dir=\"rtl\">דָּבָר</span>) <span class=\"greek\">τὸν</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ἐκράτησαν</span> trataram do assunto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:10</a>; cf. Mt. 21:24 (veja 1a<span class=\"greek\">β</span>, no início). <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">σοι</span> <span class=\"greek\">μερὶς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">τούτῳ</span> não tens parte nesta questão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:21</a>. <span class=\"greek\">ἰδεῖν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">λόγου</span> <span class=\"greek\">τούτου</span> examinar esta questão 15:6. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> <span class=\"greek\">λόγον</span> ter uma queixa contra alguém (cf. Demosth. 35, 55 <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τούτους</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span>; PIand 16, 3 <span class=\"greek\">δίκαιον</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">σέ</span>) 19:38. <span class=\"greek\">παρεκτὸς</span> <span class=\"greek\">λόγου</span> <span class=\"greek\">πορνείας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:32</a>; 19:9 variante textual (2d também é provável).—Possivelmente também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:32</a> falou francamente sobre o assunto (mas veja 1a<span class=\"greek\">β</span> acima).</p><p class=\"entry-text\">ⓑ quanto a produções literárias ou oratórias: a livros individuais de uma obra (Hdt. 5, 36 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πρώτῳ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">λόγων</span>; Pla., Parmen. 2, 127d <span class=\"greek\">ὁ</span> <span class=\"greek\">πρῶτος</span> <span class=\"greek\">λόγος</span>; Philo, Omn. Prob. Lib. 1 <span class=\"greek\">ὁ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">πρότερος</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">ἡμῖν</span>, <span class=\"greek\">ὦ</span> <span class=\"greek\">Θεόδοτε</span>, <span class=\"greek\">περὶ</span> <span class=\"greek\">τοῦ</span> … ) tratado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:1</a> (sobre o prólogo de Atos, veja: AHilgenfeld, ZWT 41, 1898, 619ff; AGercke, Her 29, 1894, 373ff; RLaqueur, Her 46, 1911, 161ff; Norden, Agn. Th. 311ff; JCreed, JTS 35, ’34, 176–82; Goodsp., Probs. 119–21). <span class=\"greek\">Παπίας</span> … <span class=\"greek\">πέντε</span> <span class=\"greek\">λόγους</span> <span class=\"greek\">κυριακῶν</span> <span class=\"greek\">λογίων</span> <span class=\"greek\">ἔγραψεν</span> Papias (11:1; cf. 3:1 e; 11:2; 12:2).—<span class=\"greek\">περὶ</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">πολὺς</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> sobre isso temos muito a dizer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:11</a>. Hebreus é descrito como <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">παρακλήσεως</span> uma palavra de exortação (em forma literária) 13:22. Quanto a escritos que integram as Sagradas Escrituras <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">Ἠσαί̈ου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:38</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">νόμῳ</span> <span class=\"greek\">γεγραμμένος</span> 15:25; <span class=\"greek\">ὁ</span> <span class=\"greek\">προφητικὸς</span> <span class=\"greek\">λ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:19</a>; 2 Cl 11:2 (citação de origem desconhecida); AcPl Ha 8, 27//BMM recto 35 (Just., D. 77, 2 al.). <span class=\"greek\">ὁ</span> <span class=\"greek\">ἅγιος</span> <span class=\"greek\">λ</span>. a palavra santa 1 Cl 56:3. <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">γεγραμμένος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.54\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:54</a> (Is 25:8 e Os 13:14 seguem-se). Pl. <span class=\"greek\">οἱ</span> <span class=\"greek\">λόγοι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">προφητῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:15</a>. <span class=\"greek\">ὡς</span> <span class=\"greek\">γέγραπται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">βίβλῳ</span> <span class=\"greek\">λόγων</span> <span class=\"greek\">Ἠσαί̈ου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:4</a> (Pla., 7th Epistle 335a <span class=\"greek\">πείθεσθαι</span> <span class=\"greek\">ἀεὶ</span> <span class=\"greek\">χρὴ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">παλαιοῖς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἱεροῖς</span> <span class=\"greek\">λόγοις</span>; TestJob 1:1 <span class=\"greek\">βίβλος</span> <span class=\"greek\">λόγων</span> <span class=\"greek\">Ἰώβ</span>; ParJer 9:32 variante textual <span class=\"greek\">τὰ</span> <span class=\"greek\">λοιπὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λόγων</span> <span class=\"greek\">Ἱερεμίου</span>; ApcEsdr 1:1 <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀποκάλυψις</span> <span class=\"greek\">τοῦ</span> … <span class=\"greek\">Ἐσδράμ</span>; ApcSed prol.; Just., D. 72, 3f).—Quanto ao conteúdo do Apocalipse: <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀναγινώσκων</span> <span class=\"greek\">τ</span>. <span class=\"greek\">λόγους</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">προφητείας</span> 1:3. <span class=\"greek\">οἱ</span> <span class=\"greek\">λόγοι</span> (<span class=\"greek\">τ</span>. <span class=\"greek\">προφητείας</span>) <span class=\"greek\">τ</span>. <span class=\"greek\">βιβλίου</span> <span class=\"greek\">τούτου</span> 22:7, 9f, 18f.</p><p class=\"entry-text\">② cômputo, contagem</p><p class=\"entry-text\">ⓐ prestação formal de contas, especialmente das próprias ações, frequentemente com extensão figurada da terminologia comercial; conta, contas, balanço <span class=\"greek\">λόγον</span> <span class=\"greek\">δοῦναι</span> (Hdt. 8, 100; X., Cyr. 1, 4, 3; Diod S 3, 46, 4; SIG 1099, 16; BGU 164, 21; Jos., Ant. 16, 120; Just., D. 115, 6) prestar contas, fazer um balanço <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">δώσει</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:12</a>. Também <span class=\"greek\">λ</span>. <span class=\"greek\">ἀποδοῦναι</span> em uso absoluto (Just., D. 116, 1 al.; Diod S 16, 56, 4; 19, 9, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:17</a>. <span class=\"greek\">τινί</span>, a alguém (Diod S 16, 27, 4; Plut., Alcib. 7, 3; Chariton 7, 6, 2; SIG 631, 13 <span class=\"greek\">τᾷ</span> <span class=\"greek\">πόλει</span>; 2 Ch 34:28; Da 6:3 Theod.; Jos., Bell. 1, 209) <span class=\"greek\">τῷ</span> <span class=\"greek\">ἑτοίμως</span> <span class=\"greek\">ἔχοντι</span> <span class=\"greek\">κρῖναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:5</a>. <span class=\"greek\">τινὸς</span>, de alguma coisa (SIG 1044, 46; 1105, 10 <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀναλώματος</span>; Jos., Ant. 19, 307) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:2</a> (aqui <span class=\"greek\">λ</span>. com o artigo; quanto à submissão a uma auditoria, cf. Aeschin. 3, 22). Semelhantemente, <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> (Diod S 18, 60, 2 <span class=\"greek\">δοὺς</span> <span class=\"greek\">αὑτῷ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">λόγον</span>=fazendo um balanço [ponderando] consigo mesmo; BGU 98, 25 <span class=\"greek\">περὶ</span> <span class=\"greek\">τούτου</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:40</a>. <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span>, acerca de alguém Hv 3, 9, 10.—<span class=\"greek\">αἰτεῖν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> exigir de alguém explicações sobre alguma coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:15</a> (cf. Pla., Pol. 285e; Dio Chrys. 20 [37], 30; Apc4Esdr Fgm. b <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οἰκείου</span> <span class=\"greek\">ἔργου</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">ἀπαιτηθήσεται</span>; Just., A I, 17, 4. Quanto a outra perspectiva, veja d abaixo.).—Quanto à responsabilidade bancária <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (PStras 72, 10 [século III d.C.] <span class=\"greek\">ὁ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">λ</span>.; PHerm 108 [século III d.C.] <span class=\"greek\">λ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Σαραπείου</span>) em jogo de palavras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:2</a> (com <span class=\"greek\">τράπεζα</span>, veja esse verbete, 1c); veja também 1a<span class=\"greek\">β</span>.—Quanto a um título de lançamento em livro contábil (POxy 1333 [séculos II/III d.C.] <span class=\"greek\">δὸς</span> <span class=\"greek\">αὐτῳ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">θεωρικῶν</span>=lance-o a crédito sob «festividades»; quanto a outros exemplos, veja Preisig., Wörterbuch s.v. <span class=\"greek\">λ</span>. 14; veja também Fachwörter 119) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:6</a> (a ideia é que a «lista» de israelitas feita por Deus é exata; quanto a <span class=\"greek\">ἐκπίπτω</span> no sentido de «não apresenta falhas», veja a acepção 4 daquele verbete); v. 9 (a «contagem» é abarcada metonimicamente pela promessa divina); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:14</a> (todas as obrigações morais se reúnem num só «lançamento»: ‘amarás teu próximo como a ti mesmo’; quanto à associação comercial de <span class=\"greek\">ἀναλίσκω</span> no v. 15, que completa o jogo de palavras, veja o respectivo verbete). Os contextos dessas três passagens sugerem forte probabilidade de associações comerciais; para outra interpretação, veja 1a<span class=\"greek\">β</span>.</p><p class=\"entry-text\">ⓑ liquidação (de uma conta) (<span class=\"greek\">εἰς</span> <span class=\"greek\">λόγον</span> termo técnico comercial «na liquidação de uma conta» POxy 275, 19; 21) <span class=\"greek\">εἰς</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">δόσεως</span> <span class=\"greek\">κ</span>. <span class=\"greek\">λήμψεως</span> na liquidação de uma conta recíproca (literalmente «de dar e receber», «de débito e crédito») <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:15</a> (cf. Plut., Mor. 11b <span class=\"greek\">λόγον</span> <span class=\"greek\">δοῦναι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λαβεῖν</span>; formulação paralela POxy 1134,10 [421 a.d.] <span class=\"greek\">λ</span>. <span class=\"greek\">λήμματος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐξοδιασμοῦ</span>=livro contábil de receitas e despesas); quanto aos termos contábeis correlatos <span class=\"greek\">δόσις</span> e <span class=\"greek\">λήμψις</span>, veja PCairMasp 151, 208 [Vséculo I d.C.]. As mesmas ideias estão subjacentes a <span class=\"greek\">εἰς</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">ὑμῶν</span> creditado à vossa conta vs 17.—<span class=\"greek\">συναίρειν</span> <span class=\"greek\">λόγον</span> acertar contas (BGU 775, 18f. A voz média no mesmo significado PFay109, 6 [século I d.C.]; POxy 113, 27f.—Dssm., LO 94 [LAE 118f]) <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:23</a>; 25:19.</p><p class=\"entry-text\">ⓒ consideração, respeito, atenção <span class=\"greek\">εἰς</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">τινός</span> com relação a, em consideração a (Thu. 3, 46, 4; Demosth. 19, 142 <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀρετῆς</span> <span class=\"greek\">λόγον</span>; Polyb. 11, 28, 8; Ath. 31, 1; Ael. Aristid. 39 p. 743 D.: <span class=\"greek\">εἰς</span> <span class=\"greek\">δεινότητος</span> <span class=\"greek\">λ</span>.) <span class=\"greek\">εἰς</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τιμῆς</span> IPhld 11:2. <span class=\"greek\">εἰς</span> <span class=\"greek\">λ</span>. <span class=\"greek\">θεοῦ</span> ISm 10:1.</p><p class=\"entry-text\">ⓓ razão ou causa de algo, motivo, fundamento (Just., D. 94, 3 <span class=\"greek\">δότε</span> <span class=\"greek\">μοι</span> <span class=\"greek\">λόγον</span>, <span class=\"greek\">ὅτου</span> <span class=\"greek\">χάριν</span> … ; Ath. 30, 3 <span class=\"greek\">τὶς</span> <span class=\"greek\">γὰρ</span> … <span class=\"greek\">λόγος</span>; Dio Chrys. 64 [14], 18 <span class=\"greek\">ἐκ</span> <span class=\"greek\">τούτου</span> <span class=\"greek\">τ</span>. <span class=\"greek\">λόγου</span>; Appian, Hann. 29 §126 <span class=\"greek\">τῷ</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">λόγῳ</span>; Iambl., Vi. Pyth. 28, 155) <span class=\"greek\">τίνι</span> <span class=\"greek\">λόγω</span>; por qual motivo? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:29</a> (cf. Pla., Gorg. 512c <span class=\"greek\">τίνι</span> <span class=\"greek\">δικαίῳ</span> <span class=\"greek\">λ</span>.; Appian, Mithrid. 57 §232 <span class=\"greek\">τίνι</span> <span class=\"greek\">λόγῳ</span>;). <span class=\"greek\">λόγον</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ἐλπίδος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:15</a> (mas veja a acima); <span class=\"greek\">κατὰ</span> <span class=\"greek\">λόγον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:14</a> (veja <span class=\"greek\">κατά</span> B 5b<span class=\"greek\">β</span>). <span class=\"greek\">παρεκτὸς</span> <span class=\"greek\">λόγου</span> <span class=\"greek\">πορνείας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:32</a>; 19:9 variante textual (embora 1a<span class=\"greek\">ε</span> também seja possível).</p><p class=\"entry-text\">ⓔ <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> (<span class=\"greek\">ἐστίν</span>) com quem temos de tratar (isto é, prestar contas) (Dio Chrys. 31, 123; outros exemplos em FBleek, Hb II/1, 1836, 590ff), em sua condição de juiz (Libanius, Legat. Ulixis [=Declamatio IV] 2 F. <span class=\"greek\">τοῖς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἀδίκως</span> <span class=\"greek\">ἀποκτενοῦσι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θεοὺς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἀνθρώπους</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">γίγνεται</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:13</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θεόν</span> não é com a carne que ele tem de tratar, mas com Deus IMg 3:2.</p><p class=\"entry-text\">ⓕ Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:23</a> (veja 1a<span class=\"greek\">β</span>) <span class=\"greek\">λόγον</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἔχοντα</span> <span class=\"greek\">σοφίας</span> pode significar «apresentar argumentos em favor da sabedoria» (cf. <span class=\"greek\">λόγος</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">οὐδείς</span> Plut., Mor. 870b).</p><p class=\"entry-text\">③ a expressão independente e personificada de Deus, o Logos. A literatura aqui considerada apresenta vestígios de uma corrente de pensamento difundida no sincretismo da época, na literatura sapiencial judaica e em Fílon, cujo traço mais destacado é o conceito de Logos, a «Palavra» independente e personificada (de Deus): GJs 11:2 (palavra do anjo a Maria) <span class=\"greek\">συνλήμψῃ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">Λόγου</span> <span class=\"greek\">αὐτοῦ</span> (subentenda-se <span class=\"greek\">τοῦ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">Δεσπότου</span>). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:1ab</a>c, 14 (cf. Just., A I, 23, 2; Mel., P. 9, 61 e frequentemente em todos os apologistas, exceto Ar.). É ensino característico do quarto Evangelho que essa «Palavra» divina assumiu forma humana numa pessoa histórica, isto é, em Jesus (veja RSeeberg, Festgabe für AvHarnack ’21, 263–81.—<span class=\"greek\">Λόγος</span> com <span class=\"greek\">ζωή</span> na especulação gnóstica: Iren.1, 1, 1 [Harv. 1, 10, 4]; Aelian, VH 4, 20 <span class=\"greek\">ἐκάλουν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Πρωταγόραν</span> <span class=\"greek\">Λόγον</span>. De modo semelhante, Favorino [século II d.C.]: Vorsokr. 80 A 1 ln. 22 [em Diog. L. 9, 50] quanto a Demócrito: <span class=\"greek\">ἐκαλεῖτο</span> <span class=\"greek\">Σοφία</span>. Identificação de uma divindade com uma abstração por ela personificada: Artem. 5, 18 <span class=\"greek\">φρόνησις</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">νομίζεται</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">θεός</span> [Athena]). Cp. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:13</a>. <span class=\"greek\">εἷς</span> <span class=\"greek\">θεός</span> <span class=\"greek\">ἐστιν</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">φανερώσας</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">αὐτοῦ</span>, <span class=\"greek\">ὅς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">λόγος</span>, <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">σιγῆς</span> <span class=\"greek\">προελθών</span> há um só Deus, que se revelou por Jesus Cristo, seu Filho, que é sua «Palavra», procedente do silêncio (isto é, sem enunciado oral: de maneira transcendente) IMg 8:2 (veja <span class=\"greek\">σιγή</span>). O Senhor como <span class=\"greek\">νόμος</span> <span class=\"greek\">κ</span>. <span class=\"greek\">λόγος</span> PtK 1. Cp. Dg 11:2, 3, 7, 8; 12:9.—HClavier, TManson memorial vol., ’59, 81–93: o <span class=\"greek\">λόγος</span> eterno alexandrino também está implícito em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:12</a>; 13:7.—Veja também o «Comma Johanneum» (à bibliografia em RGG3 I, ’54 [HGreeven] acrescente-se AJülicher, GGA 1905, 930–35; AvHarnack, SBBerlAk 1915, 572f [=Studien I ’31, 151f]; MMeinertz, Einl. in d. NT4 ’33, 309–11; AGreiff, TQ 114, ’33, 465–80; CDodd, The Joh. Epistles ’46; WThiele, ZNW 50, ’59, 61–73) <span class=\"greek\">ὁ</span> <span class=\"greek\">πατήρ</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">πνεῦμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:7</a> variante textual (veja o aparato de N.; Borger, TRu 52, ’87, 57f). (Tais interpolações não eram desconhecidas. Segundo Diog. L. 1, 48, alguns sustentam que Sólon inseriu o verso que menciona os atenienses depois de Il. 2, 557.—<span class=\"greek\">τῆς</span> <span class=\"greek\">τριάδος</span>, <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λόγου</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σοφίας</span> <span class=\"greek\">αὐτοῦ</span> Theoph. Ant. 2, 15 [p. 138, 19].)—Sobre o Logos: EZeller, D. Philosophie der Griechen III 24 1903, 417–34; MHeinze, D. Lehre v. Logos in d. griech. Philosophie 1872; PWendland, Philo u. d. kynisch-stoische Diatribe (Beiträge z. Gesch. der griech. Philosophie u. Religion por Wendl. e OKern 1895, 1–75); AAall, Gesch. d. Logosidee 1896, 1899; MPohlenz, D. Stoa ’48f, I 482; 490 (index); LDürr, D. Wertung des göttl. Wortes im AT u. im ant. Orient ’38 (§9 of the Joh. Logos); EBréhier, Les idées philosophiques et religieuses de Philon d’Alexandrie 1907, 83–111; (2 ’25); JLebreton, Les théories du Logos au début de l’ère chrétienne 1907; ESchwartz, NGG 1908, 537–56; GVos, The Range of the Logos-Title in the Prologue of the Fourth Gospel: PTR 11, 1913, 365–419; 557–602; RHarris, The Origin of the Prologue to St. John’s Gospel 1917, Athena, Sophia and the Logos: BJRL 7, 1, 1922 p. 56–72; M-JLagrange, Vers le Logos de S. Jean: RB 32, 1923, 161–84, Le Logos de Philon: ibid. 321–71; HLeisegang, Logos: Pauly-W. XIII 1926, 1035–81; TGlasson, Heraclitus’ Alleged Logos Doctr., JTS 3, ’52, 231–38.—NWeinstein, Z. Genesis d. Agada 1901, 29–90; Billerb. II 302–33.—Rtzst., Zwei religionsgeschichtl. Fragen 1901, 47–132, Mysterienrel.3 1927, 428 index; WBousset, Kyrios Christos2 1921, 304ff; 316f; JKroll, D. Lehren d. Hermes Trismegistos1914, 418 index.—RBultmann, D. religionsgesch. Hintergrund des Prol. z. Joh.: HGunkel Festschr., 1923, II 1–26, Comm. ’41, 5ff; AAlexander, The Johannine Doctrine of the Logos: ET 36, 1925, 394–99; 467–72; (Rtzst. and) HSchaeder, Studien z. antiken Synkretismus 1926, 306–37; 350; GAvdBerghvanEysinga, In den beginne was de Logos: NThT 23, ’34, 105–23; JDillersberger, Das Wort von Logos ’35; RBury, The 4th Gosp. and the Logos-Doctrine ’40; EMay, CBQ 8, ’46, 438–47; GKnight, From Moses to Paul ’49, 120–29. TW IV 76–89; 126–40 (a respeito, veja SLyonnet, Biblica 26, ’45, 126–31); CStange, ZST 21, ’50, 120–41; MBoismard, Le Prologue de St. Jean ’53; HLangkammer, BZ 9, ’65, 91–94; HRinggren, Word and Wisdom [hipostatização no Oriente Próximo] ’47; WEltester, Haenchen Festschr., ’64, 109–34; HWeiss, Untersuchungen zur Kosmologie etc., TU 97, ’66, 216–82; MRissi, Die Logoslieder im Prolog des vierten Evangeliums, TZ 31, ’75, 321–36; HLausberg, NAWG, Ph. ’87, 1 pp. 1–7.—B. 1262. DELG s.v. <span class=\"greek\">λέγω</span> B 1. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λόγχη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λόγχη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Pind., Hdt. e outros; ins, pap, LXX; Jos., Bell. 3, 95, Ant. 16, 315; SibOr 3, 688; empréstimo na literatura rabínica) lança <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:49</a> variante textual (HVogels, BZ 10, 1912, 396–405); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:34</a>. Na última passagem, também é possível o significado «ponta da lança» (Hdt. 1, 52; X., An. 4, 7, 16; SIG 1168, 95; 1169, 65) —B. 1390. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοιδορέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λοιδορέω</span> 1º aoristo <span class=\"greek\">ἐλοιδόρησα</span>; voz média-passiva, 3ª pessoa do plural <span class=\"greek\">ἐλοιδορήθησαν</span> (veja os dois verbetes seguintes; desde Píndaro, O. 9, 56 <span class=\"greek\">λ</span>. <span class=\"greek\">θεούς</span>; Dio Chrys. 15 [32], 89 <span class=\"greek\">θεούς</span>; Epict. 3, 4, 7 <span class=\"greek\">τὸν</span> <span class=\"greek\">Δία</span>; SIG 1109, 75ff; PPetr III, 21 [g], 19 [século III a.C.]; BGU 1007, 6; LXX; Just., Tat.; Ath. 34, 1) injuriar, insultar <span class=\"greek\">τινά</span>, alguém (X., An. 7, 5, 11; Theophr., Char. 28, 5; Dt 33:8; Jos., Bell. 2, 302, C. Ap. 2, 148) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:4</a>. <span class=\"greek\">τὸν</span> <span class=\"greek\">Χριστόν</span> MPol 9:3. Na voz passiva <span class=\"greek\">λοιδορούμενοι</span> <span class=\"greek\">εὐλογοῦμεν</span> quando somos injuriados, bendizemos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:12</a>; cf. Dg 5:15. Quanto a Cristo <span class=\"greek\">λοιδορούμενος</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀντελοιδόρει</span> quando foi injuriado, não revidou com injúrias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:23</a> (cf. o conselho de Plut., Mor. 88–89).—Schmidt, Syn. I 136–49. DELG. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοιδορία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λοιδορία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (veja o verbete anterior e o seguinte; Aristoph., Thu.+; PPetr II, 18 [1], 8; PSI 222, 14 <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ὕβρεως</span> <span class=\"greek\">κ</span>. <span class=\"greek\">λοιδοριῶν</span>; LXX; TestBenj 6:4 <span class=\"greek\">λοιδορίαν</span>; Philo; Jos., Ant. 17, 37, C. Ap. 2, 4; Tat. 27, 1; Ath. 11, 2) fala profundamente ofensiva, insulto, censura, injúria <span class=\"greek\">ἀποδιδόναι</span> <span class=\"greek\">λοιδορίαν</span> <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">λοιδορίας</span> retribuir injúria por injúria <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:9</a> (=Pol 2:2; cf. Philo, Agr. 110). <span class=\"greek\">μηδεμίαν</span> <span class=\"greek\">ἀφορμὴν</span> <span class=\"greek\">διδόναι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀντικειμένῳ</span> <span class=\"greek\">λοιδορίας</span> <span class=\"greek\">χάριν</span> não dar ao adversário ocasião (para censura) em razão das injúrias (que isso poderia provocar); talvez também simplesmente: para nos injuriar (se o adversário é humano; veja <span class=\"greek\">ἀντίκειμαι</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:14</a>.—DELG s.v. <span class=\"greek\">λοιδορέω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοίδορος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λοίδορος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (veja os dois verbetes anteriores; Eur.+; Plut.; IGR I, 307, 3) injuriador, pessoa insultuosa (assim em Plut., Mor. 177d; Sir 23:8; TestBenj 5:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:11</a>; 6:10.—DELG s.v. <span class=\"greek\">λοιδορέω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοιμικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λοιμικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (veja <span class=\"greek\">λοιμός</span> I; Hippocr. e outros; Lycophron, vs. 1205; IG XII/1, 1032, 7; SIG 731, 7 [século I a.C.]; PMich 149, 5, 8; 10 [século II d.C.]; Philo, Gig. 10) pestilento <span class=\"greek\">λ</span>. <span class=\"greek\">καιρός</span> um tempo de pestilência 1 Cl 55:1 (a menos que se trate de metáfora de sedição).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοιμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">I. <span class=\"greek\">λοιμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> pestilência (Hom.+; SIG 620, 15; 921, 58 <span class=\"greek\">λ</span>. <span class=\"greek\">ἢ</span> <span class=\"greek\">πόλεμος</span>; POxy 1666, 20; 4 Macc 15:32 variante textual; TestJud 23:3; Philo; Jos., Ant. 9, 289f al.) <span class=\"greek\">λοιμοί</span>, pragas, enfermidades (plural, como em Platão, Leg. 4, 709a; Hymn to Isis [século I a.C.] 24 P.) entre os sinais dos últimos tempos (com <span class=\"greek\">λιμός</span>, veja esse verbete, acepção 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:7</a> variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:11</a>.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοιμός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo; substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">II. <span class=\"greek\">λοιμός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (LXX) comparativo <span class=\"greek\">λοιμότερος</span></p><p class=\"entry-text\">① relativo à condição de adoentado, pestilento, doentio, quanto a aves de rapina <span class=\"greek\">ὄρνεα</span> … <span class=\"greek\">ὄντα</span> <span class=\"greek\">λοιμὰ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πονηρίᾳ</span> <span class=\"greek\">αὐτῶν</span> B 10:4. Quanto aos nomes das aves nessa passagem, veja Lev. 11:13–16. Barnabé as considera representativas de certos tipos de pessoas.</p><p class=\"entry-text\">② como substantivo, quanto a seres humanos: ameaça pública, inimigo público (1 Macc 15:21 quanto a criminosos procurados) B 10:10 (Ps 1:1 «pessoa pestilenta»). <span class=\"greek\">οἱ</span> <span class=\"greek\">λοιμότεροι</span> os mais perturbadores IPol 2:1. <span class=\"greek\">εὑρόντες</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄνδρα</span> <span class=\"greek\">τοῦτον</span> <span class=\"greek\">λοιμόν</span> verificamos que este homem é um inimigo público <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:5</a> (o substantivo <span class=\"greek\">λοιμός</span> como designação de pessoa perigosa para o bem público [cf. latim pestis] em Demosth. 25, 80; Aelian, VH 14, 11. O adjetivo em Libânio, Or. 1, 186 F. <span class=\"greek\">τὸν</span> <span class=\"greek\">λοιμὸν</span> <span class=\"greek\">Γερόντιον</span>. Veja <span class=\"greek\">Ἐλύμας</span> e OHoltzmann, ZKG 14, 1894, 495–502).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0220-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοιπός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo; advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λοιπός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (Pind., Hdt.+) em geral, «restante».</p><p class=\"entry-text\">① referente ao que sobra, especialmente após a realização de alguma ação, restante</p><p class=\"entry-text\">ⓐ como adjetivo <span class=\"greek\">αἱ</span> <span class=\"greek\">λοιπαὶ</span> <span class=\"greek\">φωναί</span> os toques de trombeta restantes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:13</a>.</p><p class=\"entry-text\">ⓑ como substantivo <span class=\"greek\">οἱ</span> <span class=\"greek\">λοιποί</span> aqueles que restaram <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:13</a>. Com genitivo (Iambl., Vi. Pyth. 35, 251) <span class=\"greek\">οἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span> 9:20.</p><p class=\"entry-text\">② referente ao que não foi citado ou incluído antes, outro, o restante de</p><p class=\"entry-text\">ⓐ como adjetivo (LXX; JosAs 2:10; ApcMos 29; Jos., Ant. 5, 129 <span class=\"greek\">αἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">φυλαί</span>; Ar. 3:2) <span class=\"greek\">οἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ἀπόστολοι</span> os outros apóstolos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.37\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:5</a>; Pol 9:1. <span class=\"greek\">αἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">παρθένοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:11</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ἔθνη</span> o restante das nações (gentios) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:17</a> variante textual <span class=\"greek\">οἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">Ἰουδαῖοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:13</a>. <span class=\"greek\">αἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ἐκκλησίαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:13</a>; IMg 15:1. <span class=\"greek\">οἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">συνεργοί</span> os outros cooperadores <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:3</a>. <span class=\"greek\">αἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">γραφαί</span> o restante das Escrituras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:16</a>. <span class=\"greek\">ὡς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">λοιπὰ</span> (<span class=\"greek\">ἰχθύδια</span>) B 10:5. <span class=\"greek\">καὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ἀρωμάτων</span> e (de) outras especiarias 1 Cl 25:2. <span class=\"greek\">τὰ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">σκῆπτρα</span> <span class=\"greek\">αὐτοῦ</span> o restante de suas tribos 32:2. <span class=\"greek\">προφῆται</span> 43:1. <span class=\"greek\">τὰ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">πάντα</span> <span class=\"greek\">ἄστρα</span> todas as outras estrelas IEph 19:2. <span class=\"greek\">τὰς</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">ἡμέρας</span> os dias restantes de (vossas) vidas Hv 4, 2, 5; cf. 5:2; m 12, 3, 2; 12, 6, 2; Hs 6, 3, 6. <span class=\"greek\">ἐντολάς</span> m 5, 2, 8; <span class=\"greek\">μέρη</span> Hs 8, 1, 15; 8, 5, 6; <span class=\"greek\">λίθοι</span> 9, 7, 2; 4; 9, 8, 2f; 5–7; 9, 9, 4. Cf. 5, 2, 9 <span class=\"greek\">τὰ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">λ</span>. (<span class=\"greek\">ἐδέσματα</span>; em oposição a <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀρκοῦντα</span> <span class=\"greek\">αὐτῷ</span>). <span class=\"greek\">σκεύη</span> Dg 2:4; <span class=\"greek\">ἄνθρωποι</span> 5:1; <span class=\"greek\">κτίσματα</span> 8:3; <span class=\"greek\">δοῦλοι</span> AcPl Ha 4, 10.—Singular: <span class=\"greek\">τῆς</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ὑπάρξεως</span> e outras posses Hs1:5. <span class=\"greek\">ἐν</span> … <span class=\"greek\">τῷ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">βίῳ</span> no restante de seu modo de vida Dg 5:4</p><p class=\"entry-text\">ⓑ como substantivo</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <span class=\"greek\">οἱ</span> <span class=\"greek\">λοιποί</span>, <span class=\"greek\">αἱ</span> <span class=\"greek\">λοιπαί</span> os outros (LXX, En; TestJob 41:1; Plut., Mor. 285d; Herodian 4, 2, 10; Jos., Bell. 3, 497; Ath. 8:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:6</a>; 27:49; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:10</a>; 18:9; 24:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:13</a> (de modo diferente CTorrey, ET 46, ’35, 428f); 16:30 D; 17:9; 27:44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:17</a> variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:21</a>; Hv 3, 2, 1; Hs 9, 22, 4; 9, 23, 2; 9, 26, 8; MPol 15:1. <span class=\"greek\">οἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">πάντες</span> todos os outros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:13</a>; AcPl Ha 5, 8 (SIG 593, 2f <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">λοιποῖς</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">φανερὰν</span> <span class=\"greek\">πεποιήκαμεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">προαίρεσιν</span>). <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">λ</span>. todos os demais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:9</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">ἀσθενείας</span> os outros que estavam enfermos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:9</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">οἱ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">ἐλπίδα</span> os demais que não têm esperança <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:13</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Θυατίροις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:24</a>. Com genitivo em seguida (TestJob 16:5 <span class=\"greek\">τὰ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">κτηνῶν</span> <span class=\"greek\">μου</span>; Lucian, Tox. 28 <span class=\"greek\">οἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">οἰκετῶν</span>) <span class=\"greek\">οἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span> outras pessoas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:11</a> (Just., D. 102, 6). <span class=\"greek\">οἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">νεκρῶν</span> os restantes dos mortos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:5</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σπέρματος</span> <span class=\"greek\">αὐτῆς</span> os restantes de sua descendência 12:17.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">λοιπά</span> as outras coisas, o restante (Appian, Bell. Civ. 5, 67 §284; TestSol 23:4; TestJob 16:5; Jos., Ant. 2, 312; Ar. 1, 1; Just., D. 56, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:34</a>; 15:37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:2</a> (mas veja Mussies 124, quanto a pessoas; cf. B-D-F §138, 1); Hs 1:4; 8, 3, 8; 8, 11, 5; 9, 2, 7ab; 9, 5, 5. <span class=\"greek\">τῶν</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀκολουθούντων</span> <span class=\"greek\">πάντων</span> todos os demais que se seguem 5, 5, 1; <span class=\"greek\">αἱ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">λοιπὰ</span> <span class=\"greek\">ἐπιθυμίαι</span> desejos de outras coisas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:19</a>.</p><p class=\"entry-text\">③ usos adverbiais (B-D-F §160; 451, 6)</p><p class=\"entry-text\">ⓐ relativos ao tempo</p><p class=\"entry-text\"><span class=\"greek\">α</span>. (<span class=\"greek\">τὸ</span>) <span class=\"greek\">λοιπόν</span> doravante, no futuro, daqui por diante (Píndaro e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:29</a> (mas veja 3b abaixo); Dg 9:2; ISm 9:1; Hv 3, 13, 2; m 5, 2, 7; Hs 5, 7, 4; AcPl Ha 6, 6. <span class=\"greek\">λοιπὸν</span> <span class=\"greek\">ἀπόκειταί</span> <span class=\"greek\">μοι</span> para o futuro está reservado para mim <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:8</a> (mas veja 3b abaixo). <span class=\"greek\">τὸ</span> <span class=\"greek\">λοιπὸν</span> <span class=\"greek\">ἐκδεχόμενος</span> aguardando então <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:13</a>. <span class=\"greek\">καθεύδετε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">λοιπόν</span>, expressão interpretada de diversas maneiras, transmite uma leve repreensão: ainda estais dormindo! ou: pretendeis continuar dormindo?; a expressão é provavelmente coloquial e muitas versões a vertem concisamente: Ainda dormindo? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:41</a>. Também possível nessa passagem: enquanto isso, estais dormindo! estais dormindo nesse intervalo? (assim <span class=\"greek\">τὸ</span> <span class=\"greek\">λ</span>. Jos., Ant. 18, 272) com o sentido: ‘Escolhestes uma bela hora para dormir!’—<span class=\"greek\">λοιπόν</span> finalmente (<span class=\"greek\">τότε</span> <span class=\"greek\">λοιπόν</span> TestJob 16:20 e TestAbr A 13 p. 92, 19 [Stone p. 32]. <span class=\"greek\">καὶ</span> <span class=\"greek\">λοιπόν</span> ‘e então’ TestAbr B 7 p. 111, 12 [Stone p. 70]; TestJob 17:5. TestJud 16:2 <span class=\"greek\">ἐὰν</span> … <span class=\"greek\">λοιπὸν</span> <span class=\"greek\">γίνεται</span> <span class=\"greek\">μέθη</span>. Jos., Ant. 6, 46; Tat. 42, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:20</a>; MPol 9:1. <span class=\"greek\">τὰ</span> <span class=\"greek\">λοιπά</span> no futuro Hs 6, 3, 6.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">λοιποῦ</span> doravante, no futuro (Hdt. 2, 109; Aristoph., Pax 1084; X., Cyr. 4, 4, 10, Oec. 10, 9; SIG 611, 17; 849, 12; PHal 1, 171 [século III a.C.]; POxy 1293, 14; GrBar 1:7; 16:10; Jos., Ant. 4, 187.—B-D-F §186, 2; Rob. 295) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:17</a>; Hs 9, 11, 3.—Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:10</a> o significado é provavelmente antes finalmente, encerrando a questão (veja b, abaixo; uma variante textual apresenta <span class=\"greek\">τὸ</span> <span class=\"greek\">λοιπόν</span>).</p><p class=\"entry-text\">ⓑ (<span class=\"greek\">τὸ</span>) <span class=\"greek\">λοιπόν</span> (Herodas 2, 92; Longus 2, 22, 2) quanto ao restante, fora isso, adicionalmente, finalmente <span class=\"greek\">λοιπὸν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">οἶδα</span> fora isso não sei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:16</a> (POxy 120, 1 [século IV d.C.] <span class=\"greek\">λοιπὸν</span> … <span class=\"greek\">οὐκ</span> <span class=\"greek\">οἶδα</span>). <span class=\"greek\">σκάψω</span> <span class=\"greek\">λοιπὸν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀμπελῶνα</span> além disso cavarei a vinha Hs 5, 2, 4. Como transição para algo novo (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:1</a>), especialmente próximo do final de uma obra literária finalmente (UPZ 78, 43 [159 a.C.]; POxy 119, 13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:1</a> (<span class=\"greek\">λ</span>. <span class=\"greek\">οὖν</span>, como em BGU 1079, 6 [41 d.C.]); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:1</a>; 1 Cl 64:1.—<span class=\"greek\">ὧδε</span> <span class=\"greek\">λοιπόν</span> (Epict. 2, 12, 24) nesse contexto, pois; além disso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:2</a>.—Em sentido inferencial, portanto (Epict. 1, 24, 1; 1, 27, 2 al.; POxy 1480, 13 [32 d.C.]; TestAbr A 7 p. 84, 27 [Stone p. 16]; TestJob 53:4) IEph 11:1; talvez também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:8</a>.—ACavallin, Eranos 39, ’41, 121–44; AFridrichsen, K. Human. Vetenskaps-Samfundet i Upps. Årsbok ’43, 24–28.—DELG s.v. <span class=\"greek\">λείπω</span>. M-M. Sv.</p></section></article>"};
